$q=trim((string)($_GET['q']??''));$membership=$PCC->tableExists('group_memberships');$where="(g.type='1' OR g.type='2')";$types='';$params=array();if($q!==''){$where.=' AND (g.name LIKE ? OR CAST(g.id AS CHAR)=?)';$types='ss';$params=array('%'.mb_substr($q,0,64).'%',$q);}$cols='g.id,g.name,g.type'.($PCC->columnExists('groups','badge')?',g.badge':',NULL badge');$join=$membership?' LEFT JOIN group_memberships gm ON gm.group_id=g.id':'';$cols.=$membership?',COUNT(gm.user_id) employees':',0 employees';$rows=$DB->PreparedAll('SELECT '.$cols.' FROM groups g'.$join.' WHERE '.$where.' GROUP BY g.id ORDER BY g.name LIMIT 500',$types,$params);
?>
